<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { consultarLibroDiario, obtenerOpcionesLibroDiario } from '../services/libroDiario'
import type { FiltrosLibroDiario, LibroDiarioData, PeriodoLibroDiario } from '../interfaces/libroDiario.interface'
const filtros=reactive<FiltrosLibroDiario>({detalle_periodo_id:null,vista:'analitica'}),periodos=ref<PeriodoLibroDiario[]>([]),data=ref<LibroDiarioData|null>(null),loading=ref(false),consultado=ref(false),error=ref('')
const message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la consulta.'
const money=(v:number|null|undefined)=>`S/ ${new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))}`
async function load(){loading.value=true;try{const r=await obtenerOpcionesLibroDiario();periodos.value=r.periodos;data.value=r.data;const vigente=r.periodos.find(p=>p.vigente);if(vigente)filtros.detalle_periodo_id=vigente.id}catch(v){error.value=message(v)}finally{loading.value=false}}
async function search(){error.value='';if(!filtros.detalle_periodo_id)return void(error.value='Seleccione un periodo contable.');loading.value=true;consultado.value=true;try{data.value=(await consultarLibroDiario(filtros)).data}catch(v){error.value=message(v);data.value=null}finally{loading.value=false}}
function clear(){filtros.detalle_periodo_id=null;filtros.vista='analitica';data.value=null;consultado.value=false;error.value=''}
onMounted(load)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/contabilidad/proceso-contable">Proceso contable</RouterLink> / Libro diario general</nav><header class="hero"><div class="mark">LD</div><div><small>MIA · CONTABILIDAD · PROCESO</small><h1>Libro diario general</h1><p>Reporte cronológico de todas las operaciones registradas en el periodo contable.</p></div></header><p v-if="error" class="flash">{{error}}</p><form class="filters" @submit.prevent="search"><label>Periodo contable *<select v-model="filtros.detalle_periodo_id"><option :value="null">Seleccione</option><option v-for="p in periodos" :key="p.id" :value="p.id">{{p.codigo}} - {{p.mes_label}} {{p.anio}}</option></select></label><label>Vista<select v-model="filtros.vista"><option value="analitica">Analítica (por tipo comprobante)</option><option value="resumida">Resumida (por cuenta)</option></select></label><footer><button type="button" class="soft" @click="clear">Limpiar</button><button :disabled="loading">{{loading?'Consultando…':'Consultar'}}</button></footer></form><div v-if="loading" class="empty">Preparando el libro diario…</div><div v-else-if="consultado&&!data" class="empty">No se encontraron movimientos para el periodo seleccionado.</div><div v-else-if="!data" class="empty">Seleccione un periodo contable para visualizar el libro diario general.</div><main v-else><header class="summary"><div><b>Periodo</b><span>{{data.periodo.codigo}} · {{data.periodo.mes_label}} {{data.periodo.anio}}</span></div><div><b>Vista</b><span>{{filtros.vista==='analitica'?'Analítica':'Resumida'}}</span></div></header><template v-if="filtros.vista==='analitica'"><section v-for="tipo in data.dataPorTipo??[]" :key="tipo.tipo_comprobante_id" class="group"><header><b>{{tipo.tipo_codigo}} - {{tipo.tipo_nombre}}</b></header><p class="concept">CONCEPTO: Del comprobante N.° <b>{{tipo.primer_numero}}</b> al N.° <b>{{tipo.ultimo_numero}}</b></p><div class="scroll"><table><thead><tr><th>Cuenta</th><th>Fecha</th><th>Descripción</th><th class="num">Debe S/</th><th class="num">Haber S/</th></tr></thead><tbody><tr v-for="(row,i) in tipo.detalles" :key="`${row.numero_comprobante}-${row.cta_contable}-${i}`"><td><b>{{row.cta_contable}}</b></td><td>{{row.fecha}}</td><td>{{row.descripcion_cuenta}}</td><td class="num">{{row.debe>0?money(row.debe):''}}</td><td class="num">{{row.haber>0?money(row.haber):''}}</td></tr><tr v-if="!tipo.detalles.length"><td colspan="5" class="center">Sin movimientos en este tipo de comprobante.</td></tr></tbody><tfoot><tr><th colspan="3">TOTAL {{tipo.tipo_codigo}} - {{tipo.tipo_nombre}}</th><th class="num">{{money(tipo.total_debe)}}</th><th class="num">{{money(tipo.total_haber)}}</th></tr></tfoot></table></div></section><div class="grand"><b>TOTAL GENERAL</b><b>{{money(data.totalGeneralDebe)}}</b><b>{{money(data.totalGeneralHaber)}}</b></div></template><div v-else class="scroll resumed"><table><thead><tr><th>Cuenta</th><th>Descripción</th><th class="num">Debe S/</th><th class="num">Haber S/</th></tr></thead><tbody><tr v-for="row in data.rows??[]" :key="row.cta_contable"><td><b>{{row.cta_contable}}</b></td><td>{{row.descripcion}}</td><td class="num">{{money(row.total_debe)}}</td><td class="num">{{money(row.total_haber)}}</td></tr><tr v-if="!data.rows?.length"><td colspan="4" class="center">Sin movimientos en el periodo seleccionado.</td></tr></tbody><tfoot class="grand-row"><tr><th colspan="2">TOTAL GENERAL</th><th class="num">{{money(data.totalDebe)}}</th><th class="num">{{money(data.totalHaber)}}</th></tr></tfoot></table></div></main></div></template>
<style scoped>
.page{--a:#c65a62;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--a);text-decoration:none}.hero{padding:20px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:48px;height:48px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.flash{padding:9px;color:#a64046;background:#fff0f0}.filters{margin-top:12px;padding:15px;display:grid;grid-template-columns:2fr 1.5fr 1fr;gap:8px;background:#fff}.filters label{display:grid;gap:5px;font-size:.49rem}.filters select{min-width:0;padding:9px;border:1px solid #d7dfe2;border-radius:6px;background:#fff;font:inherit;font-size:.52rem}.filters footer{display:flex;align-items:end;justify-content:flex-end;gap:6px}.filters button{padding:9px 12px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.52rem}.soft{color:#64727a!important;background:#edf1f3!important}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff}.summary{margin-top:14px;padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px;background:#fff}.summary div{display:grid;gap:3px;font-size:.52rem}.summary b{color:#728087}.group{margin-top:14px;background:#fff}.group>header{padding:10px 14px;border-left:5px solid var(--a);background:#edf1f3;font-size:.62rem}.concept{margin:0;padding:7px 14px;border-left:3px solid #e5a431;color:#666;background:#fff9e8;font-size:.49rem;font-style:italic}.scroll{overflow:auto}table{width:100%;min-width:750px;border-collapse:collapse;background:#fff;font-size:.5rem}th,td{padding:8px;border:1px solid #e1e7ea;text-align:left}thead{color:#fff;background:#354a55}tbody tr:nth-child(even){background:#f8f9fa}tfoot{background:#dce2e4}.num{text-align:right;font-family:monospace}.center{text-align:center;color:#7c888e}.grand{margin-top:10px;padding:11px 9px;display:grid;grid-template-columns:3fr 1fr 1fr;gap:10px;color:#fff;background:#2c3e50;font-size:.58rem;text-align:right}.resumed{margin-top:14px}.grand-row{color:#fff;background:#2c3e50}@media(max-width:700px){.filters{grid-template-columns:1fr}.filters footer{justify-content:flex-start}.summary{grid-template-columns:1fr}}
</style>
